"""Compact word/line/byte counter."""
import os
import sys
import unicodedata


def _counts(data: bytes):
    # wc counts newline characters; whitespace-delimited words; raw bytes.
    decoded = data.decode("utf-8", errors="replace")
    def width(line):
        col = 0
        for char in line:
            if char == "\t":
                col = (col // 8 + 1) * 8
            elif unicodedata.combining(char) or unicodedata.category(char) in ("Cf", "Cc"):
                continue
            else:
                col += 2 if unicodedata.east_asian_width(char) in ("W", "F") else 1
        return col
    max_line = max((width(line) for line in decoded.splitlines()), default=0)
    return data.count(b"\n"), len(decoded.split()), len(data), len(decoded), max_line


